import type { Response } from 'express';
import type { FeatureFlags } from '../config/flags';

export const rejectDisabledShare = (args: {
  flags: FeatureFlags;
  res: Response;
  isCanvas: boolean;
}): boolean => {
  const disabledFeature = [
    { isEnabled: args.flags.share.isEnabled, name: 'Share' },
    {
      isEnabled: args.flags.deployPrototype.isEnabled,
      name: 'Prototype deploy',
    },
    {
      isEnabled: !args.isCanvas || args.flags.canvasShare.isEnabled,
      name: 'Canvas share',
    },
  ].find((feature) => !feature.isEnabled);
  if (!disabledFeature) return false;
  args.res.status(403).json({
    errorCode: 'FEATURE_DISABLED',
    message: `${disabledFeature.name} is not enabled.`,
  });
  return true;
};
